// routes/auth.js (change-password part)
const express = require('express');
const bcrypt = require('bcryptjs');
const crypto = require('crypto');
const User = require('../models/User');
const auth = require('../middleware/auth'); // sets req.user from JWT
const { sendMail } = require('../utils/mail');

const router = express.Router();
const flows = new Map(); // userId -> { code, expires, verified, fails, lockedUntil }
const STRONG = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/;
const MAX_FAILS = 3, LOCK_MS = 60_000, CODE_MS = 5 * 60_000;

function state(userId) {
  if (!flows.has(userId)) flows.set(userId, { fails: 0 });
  return flows.get(userId);
}
function locked(s, res) {
  if (s.lockedUntil && s.lockedUntil > Date.now()) {
    res.status(429).json({ message: 'Too many attempts, try again later' });
    return true;
  }
  if (s.lockedUntil) { s.lockedUntil = 0; s.fails = 0; }
  return false;
}
function fail(s, res, message) {
  s.fails += 1;
  if (s.fails >= MAX_FAILS) {
    s.lockedUntil = Date.now() + LOCK_MS;
    return res.status(429).json({ message: 'Too many attempts, locked for 60 seconds' });
  }
  return res.status(400).json({ message });
}

router.post('/change-password/initiate', auth, async (req, res) => {
  const s = state(req.user.id);
  if (locked(s, res)) return;
  const user = await User.findById(req.user.id);
  if (!user) return res.status(401).json({ message: 'Unauthorized' });
  const ok = await bcrypt.compare(req.body.currentPassword || '', user.password);
  if (!ok) return fail(s, res, 'Current password is incorrect');
  s.code = String(crypto.randomInt(0, 10000)).padStart(4, '0');
  s.expires = Date.now() + CODE_MS;
  s.verified = false;
  s.fails = 0;
  await sendMail(user.email, 'Password change code', `Your code is ${s.code}`);
  res.json({ message: 'Verification code sent' });
});

router.post('/change-password/verify', auth, (req, res) => {
  const s = state(req.user.id);
  if (locked(s, res)) return;
  if (!s.code || s.expires < Date.now()) return res.status(400).json({ message: 'No active code' });
  if (String(req.body.code) !== s.code) return fail(s, res, 'Invalid code');
  s.verified = true;
  s.fails = 0;
  res.json({ message: 'Code verified' });
});

router.post('/change-password/update', auth, async (req, res) => {
  const s = state(req.user.id);
  if (locked(s, res)) return;
  if (!s.verified || s.expires < Date.now()) {
    return res.status(403).json({ message: 'Verify the code first' });
  }
  const { newPassword } = req.body;
  if (!STRONG.test(newPassword || '')) {
    return res.status(400).json({
      message: 'Password needs 8+ chars with upper, lower, digit and special character',
    });
  }
  const hash = await bcrypt.hash(newPassword, 10);
  await User.updateOne({ _id: req.user.id }, { password: hash });
  flows.delete(req.user.id); // one-time code
  res.json({ message: 'Password updated' });
});

module.exports = router;
